DROP POLICY quality_read ON public.quality_items;
CREATE POLICY quality_read ON public.quality_items FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR (public.is_ops(auth.uid()) AND kind IN ('complaints','improvements','consent','review_request','referral_request','recovery_request','standards')) OR (assigned_user_id=auth.uid() AND public.has_any_role(auth.uid(),ARRAY['veterinario','luis']::public.app_role[]) AND kind IN ('complaints','education','improvements')) OR (owner_id=auth.uid() AND kind IN ('consent','invitation','response','review_request','referral_request')) OR (kind='education' AND state='PUBLISHED' AND (payload->>'validUntil')::timestamptz>=now()) OR (kind='surveys' AND state='PUBLISHED' AND public.quality_has_invitation(id)));
DROP POLICY quality_audit_read ON public.quality_audit;
CREATE POLICY quality_audit_read ON public.quality_audit FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR EXISTS(SELECT 1 FROM public.quality_items qi WHERE qi.id=entity_id AND ((qi.assigned_user_id=auth.uid() AND public.has_any_role(auth.uid(),ARRAY['veterinario','luis']::public.app_role[])) OR (public.is_ops(auth.uid()) AND qi.kind IN ('complaints','improvements')))));
REVOKE INSERT,UPDATE,DELETE ON public.quality_items,public.quality_audit FROM authenticated,anon;